	@Test
	void namespaceAndIriHashCollisionsStillResolveAlternativeSplits(@TempDir File directory) throws Exception {
		String first = "plumless--split-collision-value";
		String second = "buckeroo--split-collision-value";
		assertEquals(ValueStoreRecordCodec.hash(ValueStoreRecordCodec.namespaceData("urn:split:" + first)),
				ValueStoreRecordCodec.hash(ValueStoreRecordCodec.namespaceData("urn:split:" + second)));
		try (CountingValueStore store = store(new File(directory, "namespace-collision"))) {
			store.startTransaction(true);
			store.storeValue(store.createIRI("urn:split:" + first, "/unrelated"));
			long id = store.storeValue(store.createIRI("urn:split:" + second, "/target"));
			store.commit();
			store.clearCaches();
			assertEquals(id, store.getId(VALUES.createIRI("urn:split:" + second + "/target")));
		}
		for (int mode = 0; mode < 3; mode++) {
			try (CountingValueStore store = store(new File(directory, "iri-collision-" + mode))) {
				store.startTransaction(true);
				store.storeValue(store.createIRI("urn:split:bucket/", first));
				long id = store.storeValue(store.createIRI("urn:split:", "bucket/" + second));
				store.commit();
				store.clearCaches();
				Value full = VALUES.createIRI("urn:split:bucket/" + second);
				if (mode == 0) {
					assertEquals(id, store.getId(full));
				} else {
					store.startTransaction(true);
					if (mode == 1) {
						assertEquals(id, store.storeValue(full));
					} else {
						long[] ids = new long[1];
						store.storeValues(new Value[] { full }, ids, 1);
						assertEquals(id, ids[0]);
					}
					store.commit();
				}
			}
		}
	}

