	@Test
	void namespacePrefixProofsCannotHideWriterCommitOrRollback(@TempDir File directory) throws Exception {
		for (boolean commit : new boolean[] { false, true }) {
			try (CountingValueStore store = store(new File(directory, "prefix-writer-" + commit));
					var readers = Executors.newSingleThreadExecutor()) {
				String namespace = "urn:shared:longnamespace:";
				assertEquals(LmdbValue.UNKNOWN_ID, store.getId(VALUES.createIRI(namespace + "initial")));
				store.startTransaction(true);
				long id = store.storeValue(store.createIRI(namespace, "person/1"));
				assertEquals(id, store.getId(VALUES.createIRI(namespace + "person/1")));
				assertEquals(LmdbValue.UNKNOWN_ID,
						readers.submit(() -> store.getId(VALUES.createIRI(namespace + "person/1"))).get());
				if (commit) {
					store.commit();
				} else {
					store.rollback();
				}
				assertEquals(commit ? id : LmdbValue.UNKNOWN_ID,
						store.getId(VALUES.createIRI(namespace + "person/1")));
				store.clearCaches();
				assertEquals(commit ? id : LmdbValue.UNKNOWN_ID,
						store.getId(VALUES.createIRI(namespace + "person/1")));
			}
		}
	}

